import{b as s,O as d,g as e,j as o}from"./chunks/framework.DSt9LnBW.js";const g=JSON.parse('{"title":"报告解读","description":"","frontmatter":{},"headers":[],"relativePath":"performance/locust/practice/report-reading/index.md","filePath":"性能测试/2.Locust/5.实战篇/25.报告解读.md","lastUpdated":1789911840000}'),a={name:"performance/locust/practice/report-reading/index.md"};function r(n,t,i,c,l,h){return d(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="报告解读" tabindex="-1">报告解读 <a class="header-anchor" href="#报告解读" aria-label="Permalink to &quot;报告解读&quot;">​</a></h1><blockquote><p>压测跑完了，你手上有一堆 CSV 和一张曲线图。但<strong>报告的价值不在于数据本身，而在于它能不能让别人据此做决定</strong>。这一章讲两件事：怎么把 Locust 的数据读对，怎么把它变成结论。</p></blockquote><h2 id="报告是给谁看的" tabindex="-1">报告是给谁看的 <a class="header-anchor" href="#报告是给谁看的" aria-label="Permalink to &quot;报告是给谁看的&quot;">​</a></h2><p>先明确受众，这决定了你该写什么：</p><table tabindex="0"><thead><tr><th>受众</th><th>关心什么</th><th>你要给的</th></tr></thead><tbody><tr><td><strong>业务方 / 产品</strong></td><td>双十一能不能扛住</td><td>一句话结论 + 安全容量数字</td></tr><tr><td><strong>后端开发</strong></td><td>哪里慢、怎么优化</td><td>慢接口清单 + 拐点位置 + 时间切片</td></tr><tr><td><strong>运维 / SRE</strong></td><td>要不要扩容、告警阈值定多少</td><td>资源曲线 + 容量余量</td></tr><tr><td><strong>测试同行</strong></td><td>你怎么测的、可不可信</td><td>脚本、场景设计、原始数据</td></tr></tbody></table><p>一份报告不可能同时满足这四类人。<strong>结论先行 + 分层展开</strong>是唯一可行的结构：最上面三句话给业务方，中间的技术细节给开发，附录放原始数据给同行。</p><h2 id="locust-到底给了你几份数据" tabindex="-1">Locust 到底给了你几份数据 <a class="header-anchor" href="#locust-到底给了你几份数据" aria-label="Permalink to &quot;Locust 到底给了你几份数据&quot;">​</a></h2><p>一次带 <code>--csv</code> 的运行会产出 4 个文件，外加可选的 HTML（第 14 章<a href="/performance/locust/scenarios/soak-and-spike/">浪涌与稳定性测试</a>讲过文件清单，这里讲<strong>各自怎么用</strong>）：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th><th>口径</th><th style="text-align:center;">用途</th></tr></thead><tbody><tr><td><code>xxx_stats.csv</code></td><td>每个接口一行 + <code>Aggregated</code> 汇总</td><td><strong>全程累计</strong></td><td style="text-align:center;">最终结论、验收判定</td></tr><tr><td><code>xxx_stats_history.csv</code></td><td>按时间采样，每 1 秒一行</td><td><strong>当前值（10 秒滑动窗口）</strong></td><td style="text-align:center;">看趋势、定位劣化时点</td></tr><tr><td><code>xxx_failures.csv</code></td><td>失败请求按错误类型聚合</td><td>全程累计</td><td style="text-align:center;">排查错误分布</td></tr><tr><td><code>xxx_exceptions.csv</code></td><td>脚本异常明细</td><td>全程累计</td><td style="text-align:center;">排查脚本 bug</td></tr><tr><td><code>xxx.html</code></td><td>自包含的可视化报告</td><td>全程累计</td><td style="text-align:center;">交付、存档、发给别人</td></tr></tbody></table><p>生成 HTML 报告：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locustfile.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --csv=reports/stage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --csv-full-history</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --html=reports/stage.html</span></span></code></pre></div><blockquote><p><code>--html</code> 产出的文件是<strong>自包含的</strong>（CSS/JS 都内联），单文件发给别人就能打开，不依赖 Locust 环境。这是交付报告时最省事的形式。</p></blockquote><h2 id="⚠️-最大的误读-两套百分位口径" tabindex="-1">⚠️ 最大的误读：两套百分位口径 <a class="header-anchor" href="#⚠️-最大的误读-两套百分位口径" aria-label="Permalink to &quot;⚠️ 最大的误读：两套百分位口径&quot;">​</a></h2><p>这是读懂 Locust 报告最重要的一件事，也是最容易踩的坑：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_stats.csv          →  百分位 = 整个压测期间的累计值</span></span>
<span class="line"><span>_stats_history.csv  →  百分位 = 最近约 10 秒的滑动窗口值</span></span></code></pre></div><p><strong>同一时刻，这两个数字可以差好几倍，而且都没错。</strong></p><p>滑动窗口的大小由 <code>CURRENT_RESPONSE_TIME_PERCENTILE_WINDOW</code> 控制，官方默认 <strong>10 秒</strong>。也就是说，压测跑到第 5 分钟时，界面上显示的 <code>95%</code> 反映的是&quot;<strong>最近 10 秒</strong>里 95% 的请求有多快&quot;，而不是&quot;从开始到现在&quot;。</p><h3 id="这个差异会怎么骗你" tabindex="-1">这个差异会怎么骗你 <a class="header-anchor" href="#这个差异会怎么骗你" aria-label="Permalink to &quot;这个差异会怎么骗你&quot;">​</a></h3><p><strong>场景一：先快后慢 —— 界面在报警，最终报告却挺好看</strong></p><p>压测前 4 分钟 P95 都是 80ms，最后一分钟劣化到 800ms。</p><table tabindex="0"><thead><tr><th>数据源</th><th>P95</th></tr></thead><tbody><tr><td>跑到第 5 分钟时界面上显示</td><td><strong>800ms</strong>（最近 10 秒）</td></tr><tr><td>最终 <code>_stats.csv</code></td><td>约 <strong>150ms</strong>（5 分钟累计，被前 4 分钟稀释）</td></tr></tbody></table><p>如果你只看最终 CSV，<strong>会漏掉最后那段严重的劣化</strong>。</p><p><strong>场景二：先慢后快 —— 累计值掩盖前期问题</strong></p><p>压测刚开始有 1 分钟的冷启动/缓存预热，P95 高达 2 秒，之后再没超过 100ms。最终累计 P95 可能仍然偏高，让人误以为&quot;系统整体慢&quot;，其实是启动阶段的问题。</p><blockquote><p><strong>结论：<code>_stats.csv</code> 回答&quot;整个压测平均表现如何&quot;，<code>_stats_history.csv</code> 回答&quot;什么时候变坏的&quot;。两个都要看，且不能用前者替代后者。</strong></p></blockquote><h3 id="实践建议-用-reset-stats-切掉启动阶段" tabindex="-1">实践建议：用 <code>--reset-stats</code> 切掉启动阶段 <a class="header-anchor" href="#实践建议-用-reset-stats-切掉启动阶段" aria-label="Permalink to &quot;实践建议：用 \`--reset-stats\` 切掉启动阶段&quot;">​</a></h3><p>如果只关心稳态表现，可以让 Locust 在用户爬升完成后<strong>把统计清零</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locustfile.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-stats</span></span></code></pre></div><p>这样累计值就是从稳态开始算的，<code>_stats.csv</code> 和 <code>_stats_history.csv</code> 的口径也就基本一致了。</p><blockquote><p>分布式模式下 <code>--reset-stats</code> <strong>需要在 master 和所有 worker 上都加上</strong>，否则统计对不齐。</p></blockquote><h2 id="平均值是个陷阱" tabindex="-1">平均值是个陷阱 <a class="header-anchor" href="#平均值是个陷阱" aria-label="Permalink to &quot;平均值是个陷阱&quot;">​</a></h2><p>Locust 报告里同时给了 <code>Average</code> 和多个百分位。<strong>优先看 P95/P99，平均值只做参考</strong>。</p><p>原因：平均值会被极端值和技术性因素扭曲。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1000 个请求：990 个耗时 50ms，10 个耗时 5000ms</span></span>
<span class="line"><span>平均值 = (990×50 + 10×5000) / 1000 = 99.5ms      ← 看着还行</span></span>
<span class="line"><span>P95    = 50ms                                     ← 95% 用户很快</span></span>
<span class="line"><span>P99    = 5000ms                                   ← 1% 用户卡了 5 秒</span></span></code></pre></div><p><strong>平均值 99.5ms 掩盖了&quot;每 100 个用户就有 1 个卡 5 秒&quot;这个事实。</strong> 而性能问题恰恰常常出现在尾部——超时、重试、连接池打满，都只影响少数请求，但影响的是真实用户。</p><table tabindex="0"><thead><tr><th>指标</th><th>读它回答什么问题</th></tr></thead><tbody><tr><td><code>Average</code></td><td>整体量级（<strong>别单独下结论</strong>）</td></tr><tr><td><code>P50 / Median</code></td><td>典型用户的体验</td></tr><tr><td><code>P95</code></td><td><strong>尾延迟起点，验收主要看它</strong></td></tr><tr><td><code>P99</code></td><td>极端情况，决定超时阈值设多少</td></tr><tr><td><code>Max</code></td><td>有没有离谱的慢请求（常有偶发噪声，看趋势不看单点）</td></tr></tbody></table><h2 id="逐列读-stats-csv" tabindex="-1">逐列读 <code>_stats.csv</code> <a class="header-anchor" href="#逐列读-stats-csv" aria-label="Permalink to &quot;逐列读 \`_stats.csv\`&quot;">​</a></h2><p>打开 <code>stage_stats.csv</code>，每一行是一个请求名（<code>Aggregated</code> 是全部加总）：</p><table tabindex="0"><thead><tr><th>列</th><th>含义</th><th>怎么用</th></tr></thead><tbody><tr><td><code>Request Count</code></td><td>总请求数</td><td>算流量比例（第 23 章验收用）</td></tr><tr><td><code>Failure Count</code></td><td>失败数</td><td>乘以比例得失败率，<strong>必须接近 0</strong></td></tr><tr><td><code>Median Response Time</code></td><td>P50，毫秒</td><td>典型体验</td></tr><tr><td><code>Average Response Time</code></td><td>平均值</td><td>参考</td></tr><tr><td><code>Min</code> / <code>Max</code></td><td>最快 / 最慢</td><td>抓异常请求</td></tr><tr><td><code>Average Content Size</code></td><td>平均响应体大小（字节）</td><td>换算带宽，<strong>排查&quot;是不是返回体太大&quot;</strong></td></tr><tr><td><code>Requests/s</code></td><td>每秒请求数（吞吐）</td><td><strong>容量核心指标</strong></td></tr><tr><td><code>Failures/s</code></td><td>每秒失败数</td><td>看错误是否集中在某段时间</td></tr><tr><td><code>50%</code> … <code>100%</code></td><td>各百分位（毫秒）</td><td>P95/P99 是重点</td></tr></tbody></table><p>两个容易读错的地方：</p><p><strong>1）<code>Average Content Size</code></strong>。如果某个接口响应体特别大（比如返回了全量商品列表），它会同时拖慢响应时间和占满带宽。这时候优化方向不是&quot;加机器&quot;，而是&quot;改分页/改字段&quot;。</p><p><strong>2）响应时间列是&quot;成功 + 失败&quot;合并统计的</strong>，别以为它只算成功请求。Locust 对所有请求都无条件记录响应时间（源码 <code>runners.py</code> 的 request 监听器直接调 <code>stats.log_request</code>，没有任何成功与否的判断），失败请求的耗时照样进 <code>Median</code> / <code>Average</code> / <code>Max</code> / 各百分位。所以想定位&quot;慢的是哪些失败请求&quot;，要看 <code>_failures.csv</code>（按错误类型分行），不能指望这几列帮你把失败挑出来。</p><blockquote><p>⚠️ <strong><code>_stats.csv</code> 里没有 <code>Total *</code> 这些列</strong>，别对着列名找。<code>Total Request Count</code> / <code>Total Failure Count</code> / <code>Total * Response Time</code> 只出现在 <strong><code>_stats_history.csv</code></strong>，含义是<strong>从测试开始到这一秒的累计值</strong>。它和同一行里的 <code>Requests/s</code>、百分位口径不同——后两者在 <code>--csv-full-history</code> 下取的是<strong>滑动窗口的当前值</strong>（源码里 <code>use_current=self.full_history</code>），这正是第 14 章<a href="/performance/locust/scenarios/soak-and-spike/">浪涌与稳定性测试</a>用来观察趋势的那套口径。</p></blockquote><h2 id="从数据到结论-报告模板" tabindex="-1">从数据到结论：报告模板 <a class="header-anchor" href="#从数据到结论-报告模板" aria-label="Permalink to &quot;从数据到结论：报告模板&quot;">​</a></h2><p>数据齐了，怎么组织成一份能交付的报告。核心原则是<strong>结论先行</strong>。下面是一份可以直接套用的样例（样例内部的小节标题用加粗表示，以免和本章的章节标题混在一起）：</p><p><strong>testing-online 性能测试报告</strong></p><p><strong>结论（给业务方）</strong></p><ul><li><strong>安全容量：120 并发用户</strong>，对应约 2260 RPS</li><li>该并发下 P95 = 78ms、失败率 0%，满足验收标准（P95 &lt; 500ms）</li><li><strong>距容量上限还有约 30% 余量</strong>，可支撑双十一预估峰值</li></ul><p><strong>压测条件</strong></p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>脚本</td><td>locustfile.py（浏览 70% / 购买 25% / 运营 5%）</td></tr><tr><td>负载形状</td><td>5 级阶梯，20 → 200 用户，每级 120s</td></tr><tr><td>被测环境</td><td>本地 Node.js 服务 + 单机 Locust</td></tr><tr><td>压测机</td><td>Apple Silicon 10 核，Locust 2.34.0</td></tr></tbody></table><p><strong>关键发现</strong></p><p><strong>1）拐点在 150 并发</strong></p><table tabindex="0"><thead><tr><th>用户数</th><th>RPS</th><th>较上档</th><th>P95 (ms)</th><th>失败率</th></tr></thead><tbody><tr><td>100</td><td>2260</td><td>+91.5%</td><td>78</td><td>0.00%</td></tr><tr><td><strong>150</strong></td><td><strong>2810</strong></td><td><strong>+24.3%</strong></td><td><strong>210</strong></td><td><strong>0.12%</strong></td></tr><tr><td>200</td><td>2830</td><td>+0.7%</td><td>690</td><td>3.40%</td></tr></tbody></table><p>RPS 涨幅在 150 用户处从 +91.5% 骤降到 +24.3%，同时 P95 从 78ms 跳到 210ms—— <strong>吞吐增长停滞 + 响应时间抬头，两个信号同时出现，判定拐点。</strong></p><p><strong>2）瓶颈是 CPU</strong></p><p>拐点出现时服务端 CPU 达 85%，压测机 CPU 仅 40%，<strong>瓶颈在被测服务</strong>。</p><p><strong>3）慢接口 Top 3</strong></p><table tabindex="0"><thead><tr><th>接口</th><th>P95 (ms)</th><th>原因</th></tr></thead><tbody><tr><td><code>POST /api/orders</code></td><td>480</td><td>同步多步写入（扣库存、清购物车、失效缓存）</td></tr><tr><td><code>GET /api/products?page=[page]</code></td><td>210</td><td>返回体偏大</td></tr><tr><td><code>GET /api/cart</code></td><td>160</td><td>每次查库</td></tr></tbody></table><p><strong>建议</strong></p><ol><li>告警阈值按 100 并发设置，留 30% 余量</li><li><code>POST /api/orders</code> 建议优化写入路径（当前是同步多步写入），P95 是其他接口的 3 倍</li><li>商品列表接口建议默认 <code>pageSize=10</code>，当前响应体平均 82KB</li></ol><p><strong>附录</strong></p><ul><li>原始数据：<code>reports/stage_stats.csv</code>、<code>reports/stage_stats_history.csv</code></li><li>完整报告：<code>reports/stage.html</code></li><li>脚本：<code>locustfile.py</code></li></ul><p>这份模板里最值钱的是&quot;<strong>拐点在 150 并发 + 瓶颈是 CPU</strong>&quot;这两句——把一堆数字收敛成了两个可执行的结论。剩下的数据都是支撑材料。</p><h2 id="常见误读清单" tabindex="-1">常见误读清单 <a class="header-anchor" href="#常见误读清单" aria-label="Permalink to &quot;常见误读清单&quot;">​</a></h2><p>自查一遍，这些坑几乎人人都踩过：</p><table tabindex="0"><thead><tr><th>误读</th><th>正确理解</th></tr></thead><tbody><tr><td>用 <code>_stats_history.csv</code> 的百分位当&quot;全程结果&quot;</td><td>那是 <strong>10 秒滑动窗口</strong>，不是累计值</td></tr><tr><td>只看最终 CSV，不看历史</td><td>会漏掉&quot;最后 1 分钟劣化&quot;这类关键问题</td></tr><tr><td>只看平均值</td><td>P95/P99 才是验收指标，平均值会被极端值扭曲</td></tr><tr><td>以为响应时间列只统计成功请求</td><td>失败请求的耗时也在里面；要找慢的失败请求查 <code>_failures.csv</code></td></tr><tr><td>把 <code>Aggregated</code> 的 P95 当每个接口的表现</td><td>汇总值会被高频快接口稀释，<strong>必须逐接口看</strong></td></tr><tr><td>报告第一段写环境和方法</td><td>结论先行，业务方不会看到第三段</td></tr><tr><td>只报&quot;能扛多少&quot;，不报&quot;余量多少&quot;</td><td>容量规划要的是余量，不是极限</td></tr></tbody></table><blockquote><p>第 5 条特别隐蔽：<code>Aggregated</code> 的 P95 是本项目所有请求的混合值。如果 <code>GET /api/products</code> 占了 55% 的流量且很快（50ms），它会把 Aggregated 的 P95 拉到很低——<strong>哪怕下单接口的 P95 已经 2 秒</strong>。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>结论先行</strong>：报告第一段就写安全容量和是否达标，技术和原始数据往后放</li><li><strong>两套百分位口径必须分清</strong>：<code>_stats.csv</code> 是全程累计，<code>_stats_history.csv</code> 是 <strong>10 秒滑动窗口</strong></li><li><strong>两个都要看</strong>：前者回答&quot;整体如何&quot;，后者回答&quot;何时变坏&quot;</li><li><strong><code>--reset-stats</code> 能切掉启动阶段</strong>（分布式要主从都加），让两个口径趋于一致</li><li><strong>优先 P95/P99</strong>，平均值只做参考</li><li><strong><code>Aggregated</code> 会稀释</strong>：慢接口的表现必须逐个接口看</li><li><strong>响应时间列含失败请求</strong>：失败请求的耗时也计在 <code>Median</code> / <code>Max</code> / 百分位里；要单独看失败请求就查 <code>_failures.csv</code></li><li><strong>容量报告要写余量</strong>，不能只写极限值</li></ul><p>到这里，一次完整的压测就走通了：设计脚本 → 还原比例 → 阶梯加压 → 解读报告。还剩最后一个问题—— 这套东西为什么用 Locust，而不是 JMeter？第 26 章<a href="/performance/locust/practice/locust-vs-jmeter/">Locust 还是 JMeter</a>给出判断标准。</p>`,70)])])}const u=s(a,[["render",r]]);export{g as __pageData,u as default};
